CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('coordinator','resource_manager','dispatcher','viewer','admin') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resources (id INT AUTO_INCREMENT PRIMARY KEY,resource_type ENUM('supply','volunteer','vehicle','shelter') NOT NULL,name VARCHAR(150) NOT NULL,capability VARCHAR(100) NOT NULL,total_qty DECIMAL(10,2) NOT NULL,available_qty DECIMAL(10,2) NOT NULL,location_zone VARCHAR(50) NOT NULL,expiry_date DATE NULL,status ENUM('available','unavailable','expired','depleted') DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT chk_rq CHECK(available_qty>=0 AND available_qty<=total_qty),INDEX(resource_type,status),INDEX(location_zone),INDEX(expiry_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requests (id INT AUTO_INCREMENT PRIMARY KEY,request_type VARCHAR(100) NOT NULL,required_capability VARCHAR(100) NOT NULL,required_qty DECIMAL(10,2) NOT NULL,allocated_qty DECIMAL(10,2) DEFAULT 0,location_zone VARCHAR(50) NOT NULL,priority ENUM('CRITICAL','HIGH','MEDIUM','LOW') NOT NULL,urgency INT DEFAULT 50,deadline DATETIME NULL,status ENUM('OPEN','PARTIALLY_FULFILLED','FULFILLED','CANCELLED') DEFAULT 'OPEN',notes TEXT,created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(status,priority)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS allocations (id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL,resource_id INT NOT NULL,proposed_qty DECIMAL(10,2) NOT NULL,approved_qty DECIMAL(10,2) NULL,score DECIMAL(6,2) NOT NULL,score_breakdown JSON NOT NULL,status ENUM('PROPOSED','PENDING_APPROVAL','APPROVED','MODIFIED','REJECTED','CONFLICT','CANCELLED') DEFAULT 'PROPOSED',is_manual_override BOOLEAN DEFAULT FALSE,override_reason VARCHAR(255),decided_by INT NULL,decided_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES requests(id),FOREIGN KEY(resource_id) REFERENCES resources(id),FOREIGN KEY(decided_by) REFERENCES users(id),INDEX(request_id),INDEX(resource_id),INDEX(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dispatches (id INT AUTO_INCREMENT PRIMARY KEY,allocation_id INT UNIQUE NOT NULL,dispatched_qty DECIMAL(10,2) DEFAULT 0,total_delivered_qty DECIMAL(10,2) DEFAULT 0,owner VARCHAR(100),status ENUM('NOT_DISPATCHED','DISPATCHED','IN_TRANSIT','DELIVERED','FAILED') DEFAULT 'NOT_DISPATCHED',dispatched_at TIMESTAMP NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(allocation_id) REFERENCES allocations(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS deliveries (id INT AUTO_INCREMENT PRIMARY KEY,dispatch_id INT NOT NULL,delivered_qty DECIMAL(10,2) NOT NULL,delivered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,recorded_by INT NOT NULL,FOREIGN KEY(dispatch_id) REFERENCES dispatches(id),FOREIGN KEY(recorded_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,entity_type ENUM('request','resource','allocation','dispatch','delivery') NOT NULL,entity_id INT NOT NULL,action VARCHAR(50) NOT NULL,actor_id INT NOT NULL,before_value JSON NULL,after_value JSON NULL,reason VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id),INDEX(entity_type,entity_id)) ENGINE=InnoDB;
